#!/bin/sh
# Historical commands actually executed, in order. Not an additional test runner.
# Each redirected command completed: SANY 0, baseline 0, clobber 12, restored 0.
XDG_RUNTIME_DIR=/run/user/1000 DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1000/bus systemd-run --user --scope --unit=m3-reconcile-model-sany --slice=app-t3code-agents.slice -p CPUQuota=200% nice -n 10 env JAVA_TOOL_OPTIONS='-XX:ActiveProcessorCount=2 -Xmx1g -XX:+UseParallelGC' /tmp/agents/irl-shield/m3-reconcile-model/java -cp OWNER_HOME/.local/share/mise/installs/http-tla2tools/1.7.4/tla2tools.jar tla2sany.SANY /tmp/agents/irl-shield/m3-reconcile-model/TwitchControl.tla > /tmp/agents/irl-shield/m3-reconcile-model/sany.command.log 2>&1
XDG_RUNTIME_DIR=/run/user/1000 DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1000/bus systemd-run --user --scope --unit=m3-reconcile-model-baseline --slice=app-t3code-agents.slice -p CPUQuota=200% nice -n 10 env JAVA=/tmp/agents/irl-shield/m3-reconcile-model/java TLA2TOOLS=OWNER_HOME/.local/share/mise/installs/http-tla2tools/1.7.4/tla2tools.jar JAVA_TOOL_OPTIONS='-XX:ActiveProcessorCount=2 -Xmx1g -XX:+UseParallelGC' OWNER_HOME/.agents/skills/statechart/scripts/statechart /tmp/agents/irl-shield/m3-reconcile-model/TwitchControl.tla --config /tmp/agents/irl-shield/m3-reconcile-model/TwitchControl.cfg --view /tmp/agents/irl-shield/m3-reconcile-model/view.mjs --out /tmp/agents/irl-shield/m3-reconcile-model/baseline > /tmp/agents/irl-shield/m3-reconcile-model/baseline.command.log 2>&1
XDG_RUNTIME_DIR=/run/user/1000 DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1000/bus systemd-run --user --scope --unit=m3-reconcile-model-clobber --slice=app-t3code-agents.slice -p CPUQuota=200% nice -n 10 env JAVA_TOOL_OPTIONS='-XX:ActiveProcessorCount=2 -Xmx1g -XX:+UseParallelGC' /tmp/agents/irl-shield/m3-reconcile-model/java -cp OWNER_HOME/.local/share/mise/installs/http-tla2tools/1.7.4/tla2tools.jar tlc2.TLC -workers 1 -fp 0 -lncheck final -metadir /tmp/agents/irl-shield/m3-reconcile-model/clobber-states -config /tmp/agents/irl-shield/m3-reconcile-model/release-clobber.cfg /tmp/agents/irl-shield/m3-reconcile-model/TwitchControl.tla > /tmp/agents/irl-shield/m3-reconcile-model/release-clobber.command.log 2>&1
XDG_RUNTIME_DIR=/run/user/1000 DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1000/bus systemd-run --user --scope --unit=m3-reconcile-model-restored --slice=app-t3code-agents.slice -p CPUQuota=200% nice -n 10 env JAVA=/tmp/agents/irl-shield/m3-reconcile-model/java TLA2TOOLS=OWNER_HOME/.local/share/mise/installs/http-tla2tools/1.7.4/tla2tools.jar JAVA_TOOL_OPTIONS='-XX:ActiveProcessorCount=2 -Xmx1g -XX:+UseParallelGC' OWNER_HOME/.agents/skills/statechart/scripts/statechart /tmp/agents/irl-shield/m3-reconcile-model/TwitchControl.tla --config /tmp/agents/irl-shield/m3-reconcile-model/TwitchControl.cfg --view /tmp/agents/irl-shield/m3-reconcile-model/view.mjs --out /tmp/agents/irl-shield/m3-reconcile-model/restored > /tmp/agents/irl-shield/m3-reconcile-model/restored.command.log 2>&1
